function QualityControl_Manual(inputs)

% Function to run Manual Quality control assessment in a MEA recording
% It is the final round in a sequence of QC steps, so we recommend a conservative approach (in particular if there is TTX control)
% It uses the output generated by "QualityControl_HyperSynch" and "QualityControl_General"
% (revised October 2026: the TTX conditions identified by "QualityControl_General" are now excluded, as documented below for "cond_low_activity";
%  it reads the compact output of "QualityControl_HyperSynch" -hs_master- or, for older files, the cell array "scores"; faster loops;
%  a condition with less than 2 spikes has frequency =0 for the minimum-activity check -it was NaN, and counted as active-)
% (optional) inputs:    structure to overwrite any variable of the sections INPUTS and PARAMETERS (e.g., inputs.folder, inputs.to_discard); see "override_inputs"
%                       when it is not provided, the values defined in the code are used

if ~parameter_set('active'), clc; end; close all;      % (revised October 2026) no "clc" while "run_pipeline" runs (it would erase its progress messages)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
system = 3;                 % =1, Ubuntu; =2, Yang's PC; =3, Yang's MacBook; =0, do not modify the MATLAB path (e.g., test harness)
if nargin < 1, inputs = struct(); end                                       % no inputs provided -> use the values defined in the code
if isfield(inputs, 'system'), system = inputs.system; end                   % the system can also be provided as an input
switch system
    case 1      % Anlysis PCP - Ubuntu
        addpath(genpath('/home/cortex/Documents/Yang'));
    case 2      % Yang's PC - GitHub
        addpath(genpath('C:\Users\Yang\OneDrive - Harvard University\Documents\GitHub\MEA-analysis\'));
    case 3      % Yang's MacBook
        addpath(genpath('/Users/sungminyang/Documents/GitHub/CellCircuit'));
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

folder = '/path/to/recording_folder';
file_data = 'recording_name';

to_discard = [];            % list of clusters to be discarded (the indexes are defined after eliminating the "silent" clusters)    

option_main = 3;            % =0, show the clusters that do not meet the threshold for activity level ("minimum_activity")
                            % =1, plot raster plots for all units
                            % =2, plot firing frequency vs CV of ISI, firing frequency vs LVR, and raster plot for outstanding clusters
                            % =3, selet clusters to discard (before waveform_based classification) and plot them againts good clusters
                            % =4, run waveform-based classification (only for spike-sorted by 3Brain) and plot the good clusters (WARNING: make sure you run it after completing the other steps)
                            % =5, plot the clusters discarded based on hypersynchronicity

option_saveComplete = 1;    % option to save the results and end the manual curation

minimum_activity = 0.04;    % threshold for the activity level, in Hz (default: 0.04 Hz -> 1/25sec)
cond_low_activity = -1;     % indexes of the conditions to analyze the minimum activity level (=-1, all experimental conditions but TTX)
                            % the unit is silent if the activity level in every condition is below the threshold

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% save the following variables in the file sprintf('%s\\%s_QCmanual.mat',folder,file_data):
%   - structure array spikeTimestamp (same structure than the output generated by "ShapeSpikeTrainData"), ONLY with good clusters   
% 	- rec_conditions:           list of the filename for the different conditions that were concatenated for the spike sorting, and the time window for each condition (in sec)
%   - n_discarded_manual:       total number of clusters discarded by "QualityControl_Manual"
%   - n_discarded_HS:           total number of clusters discarded on their Hypersinchronicity 
%   - minimum_activity:         threshold for the activity level, in Hz
%   - idx_abnormalActivity:     indexes of clusters (manually) discarded because of their abnormal pattern of activity  
%   - good_cluster(k,1):        it indicates if cluster k was accepted or discarded 
%   - n_clusterOriginal:        total number of originally identified clusters (before any quality control process)
%   - n_discarded_QCgeneral:    total number of clusters discarded by "QualityControl_General"

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%   PARAMETERS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

K_MSEC_SEC = 1/1000;                        % factor to rescale from msec to sec
METHOD_BURST = 1;                           % method for the burst detection (default: 1) 
    % Plotting parameters
N_PLOT = 30;                                % number of clusters to plot in each raster plot (default: 30)
N_OUTSTANDING = 20;                         % number of outstanding clusters (when looking at the CV, LVR and frequency) (default: 20)
SHIFT = 0.1;                                % distance between rows in a raster plot (default: 0.1)

apply_parameters('QualityControl_Manual');                                  % (revised October 2026) values of the parameter set of "run_pipeline", if any (see "pipeline_parameters")
override_inputs(inputs);                    % overwrite the INPUTS / PARAMETERS above with the ones provided as input (if any)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Load the data 

file_cleaned = fullfile(folder, sprintf('%s_cleaned.mat',file_data));
load(file_cleaned, 'spikeTimestamp','rec_conditions','Indiv_Cond','n_discarded','n_cluster0');
if ismember('cond_ttx', who('-file', file_cleaned))                         % (revised October 2026) recording conditions with TTX, identified by "QualityControl_General"
    load(file_cleaned, 'cond_ttx');                                         % before, "cond_ttx" was always replaced by NaN, so the TTX conditions were never excluded
else                                                                        % older files without this variable: no TTX condition is excluded (as before)
    cond_ttx = nan;
end

file_QC = fullfile(folder, sprintf('%s_QC.mat', file_data));
if ismember('hs_master', who('-file', file_QC))                             % (revised October 2026) compact result of "QualityControl_HyperSynch"
    load(file_QC, 'hs_master');                                             % hs_master(i,j)=true if the pair (i,j), i<j, has significant hypersynchronicity
else                                                                        % older files: only the cell array "scores"
    load(file_QC, 'scores');
    hs_master = false(size(scores));
    for i=1:size(scores,1)
        for j=i+1:size(scores,2)                                            % there is no directionality
            hs_master(i,j) = scores{i,j}.final.master == 1;                 % the master score is 1 for (i,j)
        end
    end
    clear scores
end

n_clusterOriginal = n_cluster0;
n_discarded_QCgeneral = n_discarded;
n_conditions = size(rec_conditions,1);                                      % total number of conditions to be extracted
n_clusters0 = size(spikeTimestamp,2);                                       % initial total number of clusters
if size(hs_master,1) ~= n_clusters0
    error('The results of "QualityControl_HyperSynch" do not match the number of clusters in the file "_cleaned"')
end
discarded = zeros(n_clusters0,1);
for i=1:n_clusters0                                                         % across all clusters (in order: the decision for cluster i depends on the clusters before it)
    if discarded(i,1)==0                                                    % if the cluster i has not been discarded
        discarded(hs_master(i,:),1) = 1;                                    % label all clusters j with master score =1 for (i,j) to be discarded/eliminated (and keep cluster i)
    end
end

discarded_idx = find(discarded);                                            % index of all discarded clusters (because of hypersynchronicity)
n_discarded_HS = numel(discarded_idx);                                      % total number of discarded clusters
fprintf("The total number of discarded clusters based on hypersynchronicity assessment is %g \n", n_discarded_HS)
discarded_plot = spikeTimestamp(discarded_idx);                             % save the data for discarded clusters, in case it needs to be plotted
spikeTimestamp(discarded_idx) = [];                                         % eliminate the data of discarded clusters from the main "spikeTimestamp" structure (all at once)
n_clusters = n_clusters0 - n_discarded_HS;                                  % updated total number of good clusters (after discarding the ones that did not pass the HS quality control)
if n_clusters == size(spikeTimestamp,2)
    fprintf("The total number of remaining clusters is %g \n", n_clusters)
else
    error('There is a mismatch between the number of clusters and the size of the database')
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Eliminate the clusters with too low level of activity 
% (spiking frequency calculated using the median ISI) 

active_cluster = ones(n_clusters,1); silent_cluster = zeros(n_clusters,1); freq = nan(n_clusters,1); cvUnits = nan(n_clusters,1); localVR = nan(n_clusters,1); regular_cond = []; freq_counting = nan(n_clusters,1);      % initialize variables

regular_cond = setdiff(1:n_conditions, cond_ttx);                           % list of non-TTX conditions
if cond_low_activity == -1                                                  % if all experimental conditions (except for TTX) will be assessed for low level of activity
   cond_low_activity = regular_cond;                                        
end

for k=1:n_clusters                                                          % across all clusters
    n_events = 0;   length_rec = 0;   freq_cond = nan(n_conditions,1);  train = [];    % initialize the cumulative variables
    for i=1:n_conditions                                                    % across all recording conditions
        ini = Indiv_Cond{i}(k).window(1)/K_MSEC_SEC;                        % start of the condition i, in msec
        fin = Indiv_Cond{i}(k).window(2)/K_MSEC_SEC;                        % end of the condition i, in msec
        in_cond = spikeTimestamp(k).timeStamp>ini & spikeTimestamp(k).timeStamp<fin;   % spikes of cluster k within the condition i (revised October 2026: logical mask instead of "intersect" of two "find"; same result)
%         freq_cond(i) = sum(in_cond)/Indiv_Cond{i}(k).recLength;  % rough spiking frequency for cluster k during condition i, in 1/sec
        if sum(in_cond) >= 2                                                    % at least one ISI within the condition i
            freq_cond(i) = 1/median(diff(spikeTimestamp(k).timeStamp(in_cond))*K_MSEC_SEC);    % spiking frequency for cluster k during condition i, in 1/sec
        else                                                                    % (revised October 2026) less than 2 spikes: frequency =0 (before, it was NaN and
            freq_cond(i) = 0;                                                   %  NaN was never below "minimum_activity", so the condition counted as active)
        end
        if  ismember(i, regular_cond)                                           % if condition i is a non-TTX condition
            n_events = n_events + sum(in_cond);                                 % cumulative number of spikes
            length_rec = length_rec + Indiv_Cond{i}(k).recLength;               % cumulative recording time, in sec
            train = vertcat(train, spikeTimestamp(k).timeStamp(in_cond));
        end
    end
    freq(k) = 1/median(diff(train)*K_MSEC_SEC);                             % spiking frequency for cluster k during the entire recording (except TTX treatment), in 1/sec
    freq_counting(k) = n_events / length_rec;                               % rough spiking frequency for cluster k during the entire recording (except TTX treatment), in 1/sec

    aux = find(freq_cond < minimum_activity);                               % conditions in which the cluster k does NOT have enough activity level
    low_cluster = intersect(aux, cond_low_activity);                        % final list of conditions with low level of activity    
    if numel(low_cluster)>=numel(cond_low_activity)                         % if all indicated conditions have low activity level
       active_cluster(k) = 0;                                               % label the clusters with subthreshold level of activity 
    end

    if freq(k) > 0
       isi = diff(train);                                                   % isi for all units in cluster k
       cvUnits(k) = std(isi)/mean(isi);                                     % coefficient of variation for isi in cluster i (NaN for "silent" cluster)                
       % localVR(k) = lvr(train);                                             % local variation ratio for cluster k
        localVR(k) = lvr(isi);                                             % local variation ratio for cluster k
    end                                                                     % (revised October 2026: no "clear" inside the loop)
end                                                                        

nActiveCluster = sum(active_cluster);                                       % total number of active clusters 
silent_cluster(active_cluster==0) = 1;                                      % =1, "silent";  =0, active cluster
idx_active = find(active_cluster);                                          % indexes of all active clusters
spikeTrain = spikeTimestamp(idx_active);                                    % new structure with data, only for active clusters (all at once)

fprintf("The files to analyze the (minimum) level of activity are: \n");
for k=1:numel(cond_low_activity)
    fprintf("     %s \n", rec_conditions{cond_low_activity(k)});
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Manual curation

switch option_main
    
    %%%%%%%%%%%%%%%%
    case 0          % show the clusters that do not meet the threshold for activity level ("minimum_activity")
    
        figure (1)                                                          % plot firing rate vs firing CV, for all clusters
        plot(freq, cvUnits, 'ok');        hold on;
        idx_silent = find(silent_cluster);                                  % indexes of low-activity clusters
        n_silent = numel(idx_silent);                                       % total number of low-activity clusters
        if n_silent > 0
            plot(freq(idx_silent), cvUnits(idx_silent), 'pm');              % label the silent clusters that were eliminated because of low activity
            legend('all clusters', sprintf('Low activity (%g out of %g)',n_silent, n_clusters))
        else
            plot([], [], 'pm'); 
        end
        title("Firing rate vs Coefficient of Variation - All Clusters (+low activity level)");        xlabel('Firing rate (Hz)');        ylabel('ISI coefficient of variation');

        figure(2)                                                           % plot histogram distribution
        h=histogram(freq);        hold on;
        plot([minimum_activity minimum_activity], [0 max(h.Values)],':r','DisplayName','threshold');
        text(minimum_activity, max(h.Values)/2,'threshold', Color='r');
        xlabel('Firing rate (Hz)');        ylabel('Number of neurons');        title('Histogram: activity level');

    %%%%%%%%%%%%%%%%
    case 1          % plot raster plots for all units (active + silent)

        n_figures = ceil(n_clusters/N_PLOT);
        fprintf("The total number of active clusters is %g (out of %g)\n", nActiveCluster, n_clusters)
        time_end = Indiv_Cond{n_conditions}(1).window(2);   
        for k=1:n_figures
            figure(k)                                                       % figure k
            ini = 1 + N_PLOT*(k-1);                             
            fin = N_PLOT + N_PLOT*(k-1);
            fin = min(fin, n_clusters);
            idx_plot = ini:fin;                                             % indexes of the clusters to be plotted in figure k
            for i=1:numel(idx_plot)                                         % across all clusters to be plotted in figure k
                data = spikeTimestamp(idx_plot(i));                             % data for cluster i
                if ismember(idx_plot(i),idx_active)
                    color = [0 0 0];                                        % black, active unit
                else
                    color = [1 0 1];                                        % magenta, silent unit
                end
                plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)*idx_plot(i),'|',"MarkerEdgeColor", color);
                text(time_end/2, idx_plot(i)-0.5,sprintf('# %g', idx_plot(i)));    % print the label for the cluster i    
                hold on;                clear data;
            end
            for cond=1:n_conditions
                t_ini = Indiv_Cond{cond}(1).window(1);
                plot([t_ini t_ini], [ini-1 fin+1], '--r','LineWidth',2);
            end
            ylim([ini-1 fin+1]);    xlim([0 time_end]);            xlabel('Time (sec)');            ylabel('Cluster');            title(sprintf('Clusters %g to %g', ini, fin));
        end

    %%%%%%%%%%%%%%%%
    case 2          % plot firing frequency vs CV of ISI, firing frequency vs LVR, and raster plot for outstanding clusters

        cv_active = cvUnits(idx_active);        lvr_active = localVR(idx_active);        freq_active = freq_counting(idx_active);       freqisi_active = freq(idx_active);             
        [~, idx_cv] = sort(cv_active,'descend');                            % sort coefficient of variation in descending order
        [~, idx_lvr] = sort(lvr_active,'ascend');                           % sort local variation ratio in ascending order
        [~, idx_freq] = sort(freq_active,'descend');                        % sort spiking frequency in descending order
        n_interest = min(N_OUTSTANDING, nActiveCluster);
        n_interest2 = min(N_OUTSTANDING*2,nActiveCluster);
        out_cv = idx_cv(1:n_interest2);                                     % indexes of "outstanding" clusters, based on CV (high CV)
        out_lvr = idx_lvr(1:n_interest2);                                   % indexes of "outstanding" clusters, based on LVR (low CV)
        out_freq = idx_freq(1:n_interest);                                  % indexes of "outstanding" clusters, based on frequency (high frequency)

        n_burst = nan(n_interest,1);
        for i=1:n_interest2                                                 % across all "outstanding" clusters
            BurstDetected = BurstDetection(spikeTrain(out_cv(i)).timeStamp, METHOD_BURST);
            n_burst(i) = BurstDetected.nBurst;                              % number of burst events in the "outstanding" cluster i, based on CV
        end
        [~, idx_aux] = sort(n_burst,'descend');                             % sort the number of burst events in descending order
        idx_burst = out_cv(idx_aux);                                         
        out_burst = idx_burst(1:n_interest);                                % units with high number of bursts within the high-CV

        n_burst = nan(n_interest,1);
        for i=1:n_interest2                                                 % across all "outstanding" clusters
            BurstDetected = BurstDetection(spikeTrain(out_lvr(i)).timeStamp, METHOD_BURST);
            n_burst(i) = BurstDetected.nBurst;                              % number of burst events in the "outstanding" cluster i, based on LVR
        end
        [~, idx_aux] = sort(n_burst,'ascend');                              % sort the number of burst events in ascending order
        idx_burst2 = out_lvr(idx_aux);                                         
        out_burst2 = idx_burst2(1:n_interest);                              % units with low number of bursts within the low-LVR

        figure(1)                                                           % plot firing rate vs firing CV, for all clusters
        plot(freq_active, cv_active, 'ok');        hold on;                 
        plot(freq_active(out_burst), cv_active(out_burst),'pg'); hold on;   % label the clusters with outstanding coefficient of variation for isi and number of burst events
        plot(freq_active(out_freq), cv_active(out_freq), '*r'); hold on;    % label the clusters with outstanding firing rate
        legend('all clusters', 'high CV and bursting', 'high firing');        title("Firing rate vs Coefficient of Variation - Active clusters");        xlabel('Firing rate (Hz)');        ylabel('ISI coefficient of variation');
        max_cv = max(cv_active);        max_freq = max(freq_active);
        for i=1:n_interest                                                  % id the "outstanding" clusters
%            text(freq_active(out_burst(i))+max_freq/200,cv_active(out_burst(i))+max_cv/100,sprintf('%g %g', idx_active(out_burst(i)), out_burst(i))); hold on;
%            text(freq_active(out_freq(i))+max_freq/200,cv_active(out_freq(i))+max_cv/100,sprintf('%g %g', idx_active(out_freq(i)), out_freq(i))); hold on;
            text(freq_active(out_burst(i))+max_freq/200,cv_active(out_burst(i))+max_cv/100,sprintf('%g', idx_active(out_burst(i)))); hold on;
            text(freq_active(out_freq(i))+max_freq/200,cv_active(out_freq(i))+max_cv/100,sprintf('%g', idx_active(out_freq(i)))); hold on;
        end

        figure(2)                                                           % plot some example raster plots
        subplot(2,1,1)                                                      % raster plot of clusters with high CV and bursting
        for i=1:n_interest
            idx = idx_active(out_burst(i));
            data = spikeTimestamp(idx);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);
            text(data.timeStamp(end)*K_MSEC_SEC, 1+(i-0.5)*SHIFT,sprintf('# %g', idx));            hold on;            clear data;
        end
        ylim([0.5 1.5+i*SHIFT]);        xlabel('Time (sec)');        ylabel('Cluster');        title(sprintf('Outstanding CV + bursting'));
        subplot(2,1,2)                                                      % raster plot of cluster with high level of activity (but NO high CV and bursting)
        out_noise = setdiff(out_freq, out_burst); 
        if numel(out_noise)
        for i=1:numel(out_noise)
            idx = idx_active(out_noise(i));
            data = spikeTimestamp(idx);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);
            text(data.timeStamp(end)*K_MSEC_SEC, 1+(i-0.5)*SHIFT,sprintf('# %g', idx));            hold on;            clear data;
        end
        ylim([0.5 1.5+i*SHIFT]);        xlabel('Time (sec)');        ylabel('Cluster');        title(sprintf('Outstanding Firing rate (but NO high CV and bursting)'));
        end

        figure(3)                                                           % plot firing rate vs firing LVR, for all clusters
        plot(freq_active, lvr_active, 'ok');        hold on;                 
        plot(freq_active(out_burst2), lvr_active(out_burst2),'pb'); hold on;% label the clusters with low local variation ratio and number of burst events
        plot(freq_active(out_freq), lvr_active(out_freq), '*r'); hold on;   % label the clusters with outstanding firing rate
        legend('all clusters', 'Low LVR and bursting', 'high firing');        title("Firing rate vs Coefficient of Variation - Active clusters");        xlabel('Firing rate (Hz)');        ylabel('ISI LVR');
        max_lvr = max(lvr_active);        max_freq = max(freq_active);
        for i=1:n_interest                                                  % id the "outstanding" clusters
            text(freq_active(out_burst2(i))+max_freq/200,lvr_active(out_burst2(i))+max_lvr/100,sprintf('%g', idx_active(out_burst2(i)))); hold on;
            text(freq_active(out_freq(i))+max_freq/200,lvr_active(out_freq(i))+max_lvr/100,sprintf('%g', idx_active(out_freq(i)))); hold on;
        end

        figure(4)                                                           % plot some example raster plots
        subplot(2,1,1)                                                      % raster plot of clusters with high CV and bursting
        for i=1:n_interest
            idx = idx_active(out_burst2(i));
            data = spikeTimestamp(idx);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);
            text(data.timeStamp(end)*K_MSEC_SEC, 1+(i-0.5)*SHIFT,sprintf('# %g', idx));            hold on;            clear data;
        end
        ylim([0.5 1.5+i*SHIFT]);        xlabel('Time (sec)');        ylabel('Cluster');        title(sprintf('Low LVR + bursting'));
        subplot(2,1,2)                                                      % raster plot of cluster with high level of activity (but NO high CV and bursting)
        out_noise2 = intersect(out_freq, out_burst2);    
        if numel(out_noise2)>0
        for i=1:numel(out_noise2)
            idx = idx_active(out_noise2(i));
            data = spikeTimestamp(idx);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);
            text(data.timeStamp(end)*K_MSEC_SEC, 1+(i-0.5)*SHIFT,sprintf('# %g', idx));            hold on;            clear data;
        end
        ylim([0.5 1.5+i*SHIFT]);        xlabel('Time (sec)');        ylabel('Cluster');        title(sprintf('Outstanding Firing rate (and low LVR)'));
        end

        figure(5)                                                           % plot the relation between the two types of frequency
        plot(freq_counting, freq, 'ok');        hold on;                 
        plot(freq_counting(idx_active(out_burst)), freq(idx_active(out_burst)),'pg'); hold on;   % label the clusters with outstanding coefficient of variation for isi and number of burst events
        plot(freq_counting(idx_active(out_freq)), freq(idx_active(out_freq)), '*r'); hold on;    % label the clusters with outstanding firing rate
        legend('all clusters', 'high CV and bursting', 'high firing');        title("Firing rate (counting spikes) vs Firing rate (from ISI)");        xlabel('Firing rate - counting (Hz)');        ylabel('Firing rate - ISI (Hz)');
        max_x = max(freq_counting);        max_y = max(freq);
        for i=1:n_interest                                                  % id the "outstanding" clusters
            text(freq_active(out_burst(i))+max_x/200,freqisi_active(out_burst(i))+max_y/100,sprintf('%g', idx_active(out_burst(i)))); hold on;
            text(freq_active(out_freq(i))+max_x/200,freqisi_active(out_freq(i))+max_y/100,sprintf('%g', idx_active(out_freq(i)))); hold on;
        end


    %%%%%%%%%%%%%%%%
    case 3          % selet clusters to discard and plot them againts good clusters

        n_tobediscarded = numel(to_discard);                                % total number of clusters to be discarded
        idx_silent = find(silent_cluster);                                  % indexes of the clusters with low level of activity

        figure(1)                                                           % raster plots
        if n_tobediscarded > 0
            subplot(3,1,1)                                                  % raster plot of all clusters to be discarded
            for i=1:n_tobediscarded                                         
                data = spikeTimestamp(to_discard(i));
                plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);
                text(data.timeStamp(end)*K_MSEC_SEC, 1+(i-0.5)*SHIFT,sprintf('# %g', to_discard(i)));                hold on;                clear data;
            end 
            ylim([0.5 1.5+i*SHIFT]);            xlabel('Time (sec)');            ylabel('Cluster');            title(sprintf('Clusters to be discarded (selected - abnormal activity)'));
        else
            fprintf('\n You have selected no clusters to be discarded \n')
        end
        if numel(idx_silent)>0
            subplot(3,1,2)                                                  % raster plot of clusters with low activity
            for i=1:min(N_PLOT,numel(idx_silent))                           
                data = spikeTimestamp(idx_silent(i));
                plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);                hold on;                clear data;
            end 
            ylim([0.5 1.5+i*SHIFT]);            xlabel('Time (sec)');            ylabel('Cluster');            title(sprintf('Clusters to be discarded (LOW activity)'));
        end
        subplot(3,1,3)                                                      % raster plot of good clusters (high CV and bursting)
        cv_active = cvUnits(idx_active);
        [~, idx_cv] = sort(cv_active,'descend');
        n_interest = min(N_OUTSTANDING,nActiveCluster);
        n_interest2 = min(N_OUTSTANDING*2,nActiveCluster);
        out_cv = idx_cv(1:n_interest2);                                     % indexes of clusters with high CV    
        n_burst = nan(n_interest,1);
        for i=1:n_interest2
            BurstDetected = BurstDetection(spikeTrain(out_cv(i)).timeStamp, METHOD_BURST);
            n_burst(i) = BurstDetected.nBurst;
        end
        [~, idx_aux] = sort(n_burst,'descend');
        idx_burst = out_cv(idx_aux);
        out_burst = idx_burst(1:n_interest);
        idx_plot = setdiff(out_burst,to_discard);
        for i=1:numel(idx_plot)
            idx = idx_active(idx_plot(i));
            data = spikeTimestamp(idx);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i*SHIFT,'|',"MarkerEdgeColor",[0 0 0]);
            text(data.timeStamp(end)*K_MSEC_SEC, 1+(i-0.5)*SHIFT,sprintf('# %g', idx));                hold on;                clear data;
        end 
        ylim([0.5 1.5+i*SHIFT]);            xlabel('Time (sec)');            ylabel('Cluster');            title(sprintf('Good Clusters'));

        figure(2)                                                           % firing rate, ISI CV and LVR for discarded clusters
        subplot(1,2,1)                                                      % firing rate vs CV
        plot(freq_counting, cvUnits, 'ok');      hold on;
        if  n_tobediscarded > 0
            plot(freq_counting(to_discard), cvUnits(to_discard), '*r');
            if ~isempty(idx_silent)
               plot(freq_counting(idx_silent), cvUnits(idx_silent), 'pm');  % label the silent clusters that were eliminated because of low activity
               legend(sprintf('all clusters (%g)',  n_clusters), sprintf('Abnoral activty (%g)', n_tobediscarded), sprintf('Low activity (%g)', numel(idx_silent)))
            else
               plot([], [], 'pm');         legend(sprintf('all clusters (%g)',  n_clusters), sprintf('Abnoral activty (%g)', n_tobediscarded))
            end
        elseif ~isempty(idx_silent)
               plot(freq_counting(idx_silent), cvUnits(idx_silent), 'pm');           % label the silent clusters that were eliminated because of low activity
               legend(sprintf('all clusters (%g)',  n_clusters), sprintf('Low activity (%g)', numel(idx_silent)))
        end
        title("Firing rate vs Coefficient of Variation - All Clusters");            xlabel('Firing rate - counting (Hz)');            ylabel('ISI coefficient of variation');
        subplot(1,2,2)                                                      % firing rate vs LVR
        plot(freq_counting, localVR, 'ok');      hold on;
        if  n_tobediscarded > 0
            plot(freq_counting(to_discard), localVR(to_discard), '*r');
            if ~isempty(idx_silent)
               plot(freq_counting(idx_silent), localVR(idx_silent), 'pm');           % label the silent clusters that were eliminated because of low activity
               legend(sprintf('all clusters (%g)',  n_clusters), sprintf('Abnoral activty (%g)', n_tobediscarded), sprintf('Low activity (%g)', numel(idx_silent)))
            else
               plot([], [], 'pm');         legend(sprintf('all clusters (%g)',  n_clusters), sprintf('Abnoral activty (%g)', n_tobediscarded))
            end
        elseif ~isempty(idx_silent)
               plot(freq_counting(idx_silent), localVR(idx_silent), 'pm');           % label the silent clusters that were eliminated because of low activity
               legend(sprintf('all clusters (%g)',  n_clusters), sprintf('Low activity (%g)', numel(idx_silent)))
        end
        title("Firing rate vs Local Variation Ratio - All Clusters");            xlabel('Firing rate - counting (Hz)');            ylabel('LVR');

    %%%%%%%%%%%%%%%%
    case 4          % classify the clusters based on their waveform (only for spikes sorted by 3Brain)
        
        fileRaw = fullfile(folder, sprintf('%s_raw.mat', file_data));
        file_existing = fullfile(folder, sprintf('%s_QCmanual.mat', file_data));
        if isfile(file_existing)
            if ~isempty(who('-file', file_existing, 'unitLabel'))
                load(file_existing,'unitLabel','spikeTimestamp');
                fprintf("\n There is previous work done for waveform-based classification. There are %g remaining clusters to be assessed \n", sum(isnan(unitLabel(:,2))));
                unitLabel = Classify3BrainWaveform(fileRaw, spikeTimestamp, unitLabel, 0);            
            else
                load(file_existing,'spikeTimestamp','good_cluster');  
                unitLabel = nan(size(spikeTimestamp,2),2);
                for j=1:size(unitLabel,1)
                    unitLabel(j,1) = spikeTimestamp(j).cluster;
                end
                unitLabel = Classify3BrainWaveform(fileRaw, spikeTimestamp, unitLabel, 1);
            end
            save(file_existing,'unitLabel',"-append");  
            fprintf("\n The result of the waveform-based classification is: %g good, %g weak, %g noise and %g incomplete \n", ...
                    numel(find(unitLabel==1)), numel(find(unitLabel==2)), numel(find(unitLabel==-1)), sum(isnan(unitLabel(:,2))));
            option_saveComplete = 0;      
        else
            good_cluster = ones(n_clusters,1);
            if sum(silent_cluster)>0
                good_cluster(find(silent_cluster)) = 0;                         % identify the clusters with low activity
            end
            if numel(to_discard)>0
                good_cluster(to_discard) = 0;                                   % identify the clusters selected to be discarded
            end
            idx_discarded_clusters = find(good_cluster==0);                     % indexes of all clusters to be discarded
            spikeTimestamp_good = spikeTimestamp;
            spikeTimestamp_good(idx_discarded_clusters) = [];                   % delete the data for all discarded clusters / keep only the data for good quality clusters (all at once)
            unitLabel = nan(size(spikeTimestamp_good,2),2);
            for j=1:size(unitLabel,1)
                unitLabel(j,1) = spikeTimestamp_good(j).cluster;
            end
            unitLabel = Classify3BrainWaveform(fileRaw, spikeTimestamp_good, unitLabel, 1);
            option_saveComplete = 1;
        end

        clear good_cluster spikeTimestamp_good
    %%%%%%%%%%%%%%%%
    case 5          % plot the clusters discarded based on hypersynchronicity

        figure(1)
        for i=1:n_clusters
            data = spikeTimestamp(i);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)*i,'|',"MarkerEdgeColor",[0 0 0]);            hold on;            clear data;
        end
        ylim([0 n_clusters+1]);        xlabel('Time (sec)');        ylabel('Cluster');        title(sprintf('Clusters with acceptable hypersynchronicity (%g)', n_clusters));

        figure(2)
        for i=1:n_discarded_HS
            data = discarded_plot(i);
            plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)*i,'|',"MarkerEdgeColor",[0 0 0]);            hold on;            clear data;
        end
        ylim([0 n_discarded_HS+1]);        xlabel('Time (sec)');        ylabel('Cluster');        title(sprintf('Clusters discarded because of their high hypersynchronicity (%g)', n_discarded_HS));
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Save the output

if option_saveComplete
    good_cluster = ones(n_clusters,1);
    if sum(silent_cluster)>0
        good_cluster(find(silent_cluster)) = 0;                             % identify the clusters with low activity
    end
    if numel(to_discard)>0
        good_cluster(to_discard) = 0;                                       % identify the clusters selected to be discarded
    end
    idx_discarded_clusters = find(good_cluster==0);                         % indexes of all clusters to be discarded
    n_discarded_manual = numel(idx_discarded_clusters);
    fprintf("The total number of manually discarded clusters is %g out of %g (%g for low activity and %g for abnormal activity) \n", n_discarded_manual, n_clusters, sum(silent_cluster),numel(to_discard)) 

    spikeTimestamp(idx_discarded_clusters) = [];                            % delete the data for all discarded clusters / keep only the data for good quality clusters (all at once)

    figure(10)                                                               % plot the raster plot of ALL good clusters
    for i=1:size(spikeTimestamp,2)
        data = spikeTimestamp(i);
        plot(data.timeStamp*K_MSEC_SEC, ones(data.nUnits,1)+i,'|',"MarkerEdgeColor",[0 0 0]);        hold on;        clear data;
    end 
    ylim([0 1+i]);    xlabel('Time (sec)');    ylabel('Cluster');    title(sprintf('ALL Good Clusters'));

    for j=1:size(rec_conditions,1)
        rec_conditions{j,2} = Indiv_Cond{j}.window;                         % add the temporal window to the variable for recording condition
    end
    idx_abnormalActivity = to_discard;
    file_output = fullfile(folder, sprintf('%s_QCmanual.mat',file_data));
    save(file_output,'spikeTimestamp','rec_conditions','minimum_activity','idx_abnormalActivity','good_cluster','n_discarded_HS','n_discarded_manual','n_clusterOriginal','n_discarded_QCgeneral');  
    fprintf("The total number of remaining good clusters is %g \n \n", size(spikeTimestamp,2))
    fprintf("The result of the manual curation has been saved \n \n")

    if option_main==4
       save(file_output,'unitLabel',"-append");  
       fprintf("\n The result of thge waveform-based classification is: %g good, %g weak, %g noise and %g incomplete \n", ...
           numel(find(unitLabel==1)), numel(find(unitLabel==2)), numel(find(unitLabel==-1)), sum(isnan(unitLabel(:,2))));
    end
end

end
